// keys: "ddaq"
// expect: exit 11
// screen: 5            *
int main(void)
{
    int x = 10, k;
    do {
        cls();
        at(5, x);
        print("*");
        k = getkey();
        if (k == 'a')
            x--;
        if (k == 'd')
            x++;
    } while (k != 'q');
    return x;
}
